import{_ as n,o as a,c as e,a3 as p}from"./chunks/framework.B7pF4b99.js";const h=JSON.parse('{"title":"02 · 開機流程","description":"","frontmatter":{},"headers":[],"relativePath":"topics/boot.md","filePath":"topics/boot.md","lastUpdated":1794275263000}'),l={name:"topics/boot.md"};function r(i,s,c,t,o,b){return a(),e("div",null,[...s[0]||(s[0]=[p(`<h1 id="_02-·-開機流程" tabindex="-1">02 · 開機流程 <a class="header-anchor" href="#_02-·-開機流程" aria-label="Permalink to &quot;02 · 開機流程&quot;">​</a></h1><p>CPU 不認識 <code>entry.S</code> 或 <code>main.c</code> 這些檔名，只會執行記憶體中的機器指令。兩個來源檔最後會被連結到同一份核心映像。</p><h2 id="磁碟開機-主機先準備什麼" tabindex="-1">磁碟開機：主機先準備什麼 <a class="header-anchor" href="#磁碟開機-主機先準備什麼" aria-label="Permalink to &quot;磁碟開機：主機先準備什麼&quot;">​</a></h2><p><code>make run-disk</code> 分成主機建置與 QEMU 開機兩個階段。主機負責交叉編譯 RISC-V 程式，並把核心安裝進 WUFS 映像；這時 WUWAOS 尚未開始執行。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HOST: make run-disk</span></span>
<span class="line"><span>============================================================</span></span>
<span class="line"><span></span></span>
<span class="line"><span>WUWAOS source</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    +-- compile kernel --&gt; build/kernel-disk.elf</span></span>
<span class="line"><span>    |                              |</span></span>
<span class="line"><span>    |                              | install into WUFS</span></span>
<span class="line"><span>    |                              v</span></span>
<span class="line"><span>    |                     build/wuwaos-cli.img</span></span>
<span class="line"><span>    |                     +------------------------+</span></span>
<span class="line"><span>    |                     | WUFS0002 filesystem    |</span></span>
<span class="line"><span>    |                     |   /boot/kernel.elf     |</span></span>
<span class="line"><span>    |                     +------------------------+</span></span>
<span class="line"><span>    |</span></span>
<span class="line"><span>    +-- compile loader --&gt; build/bootloader.elf</span></span>
<span class="line"><span>                                   |</span></span>
<span class="line"><span>                                   v</span></span>
<span class="line"><span>                          build/boot-flash.img</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br></div></div><p><code>build/kernel-disk.elf</code> 是移除符號後、供磁碟開機使用的核心 ELF。<code>build/boot-flash.img</code> 裡放的是載入器，QEMU 將它接成唯讀 flash；核心檔案則在另一顆 VirtIO 磁碟的 <code>/boot/kernel.elf</code>。此 CLI 路徑使用單顆 WUFS0002 磁碟，停用 swap，並要求 journal 無待重播紀錄。</p><h2 id="從韌體到使用者-shell" tabindex="-1">從韌體到使用者 shell <a class="header-anchor" href="#從韌體到使用者-shell" aria-label="Permalink to &quot;從韌體到使用者 shell&quot;">​</a></h2><p>QEMU 的 RISC-V CPU 啟動後，先執行 OpenSBI 韌體，再交接到 S-mode（監督模式）的 flash 載入器。以下才是客體電腦內部的開機過程。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GUEST: QEMU virt / RISC-V 64</span></span>
<span class="line"><span>============================================================</span></span>
<span class="line"><span></span></span>
<span class="line"><span>                    CPU starts</span></span>
<span class="line"><span>                        |</span></span>
<span class="line"><span>                        v</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>              | OpenSBI firmware   |</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>                        |</span></span>
<span class="line"><span>                        | hand off to S-mode</span></span>
<span class="line"><span>                        v</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>              | Flash Bootloader   |</span></span>
<span class="line"><span>              | 0x20000000         |</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>                        |</span></span>
<span class="line"><span>                        | discover VirtIO disk</span></span>
<span class="line"><span>                        v</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>              | Read WUFS          |</span></span>
<span class="line"><span>              | /boot/kernel.elf   |</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>                        |</span></span>
<span class="line"><span>                        | validate ELF, load segments into RAM</span></span>
<span class="line"><span>                        v</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>              | Kernel _start      |</span></span>
<span class="line"><span>              | 0x80200000         |</span></span>
<span class="line"><span>              | stack + clear BSS  |</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>                        |</span></span>
<span class="line"><span>                        | call kernel_main(hart_id, fdt)</span></span>
<span class="line"><span>                        v</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>              | Initialize kernel  |</span></span>
<span class="line"><span>              | devices / VM / FS  |</span></span>
<span class="line"><span>              | IRQ / timer / proc |</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>                        |</span></span>
<span class="line"><span>                        | process_start -&gt; scheduler_loop</span></span>
<span class="line"><span>                        v</span></span>
<span class="line"><span>              +--------------------+</span></span>
<span class="line"><span>              | User-mode shell    |</span></span>
<span class="line"><span>              | wuwaos/&gt;           |</span></span>
<span class="line"><span>              +--------------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br><span class="line-number">12</span><br><span class="line-number">13</span><br><span class="line-number">14</span><br><span class="line-number">15</span><br><span class="line-number">16</span><br><span class="line-number">17</span><br><span class="line-number">18</span><br><span class="line-number">19</span><br><span class="line-number">20</span><br><span class="line-number">21</span><br><span class="line-number">22</span><br><span class="line-number">23</span><br><span class="line-number">24</span><br><span class="line-number">25</span><br><span class="line-number">26</span><br><span class="line-number">27</span><br><span class="line-number">28</span><br><span class="line-number">29</span><br><span class="line-number">30</span><br><span class="line-number">31</span><br><span class="line-number">32</span><br><span class="line-number">33</span><br><span class="line-number">34</span><br><span class="line-number">35</span><br><span class="line-number">36</span><br><span class="line-number">37</span><br><span class="line-number">38</span><br><span class="line-number">39</span><br><span class="line-number">40</span><br><span class="line-number">41</span><br><span class="line-number">42</span><br><span class="line-number">43</span><br><span class="line-number">44</span><br><span class="line-number">45</span><br><span class="line-number">46</span><br></div></div><p>載入器找到 <code>/boot/kernel.elf</code> 後，檢查 ELF 標頭與可載入區段，將核心放到 RAM，再跳到核心入口。交接時保留 OpenSBI 傳來的 hart ID（硬體執行緒編號）與 FDT（裝置樹）位址。找不到磁碟、核心檔案或 ELF 不合法時，載入器會印出錯誤並停止開機。<a href="https://github.com/johnson931128/WUWAOS/blob/main/bootloader/boot.c" target="_blank" rel="noreferrer">載入器原始碼</a></p><h3 id="flash、磁碟與-ram-的關係" tabindex="-1">Flash、磁碟與 RAM 的關係 <a class="header-anchor" href="#flash、磁碟與-ram-的關係" aria-label="Permalink to &quot;Flash、磁碟與 RAM 的關係&quot;">​</a></h3><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Read-only Flash       VirtIO disk                 RAM</span></span>
<span class="line"><span>+---------------+     +--------------------+      +----------------+</span></span>
<span class="line"><span>| Bootloader    |----&gt;| /boot/kernel.elf   |-----&gt;| WUWAOS kernel  |</span></span>
<span class="line"><span>+---------------+     +--------------------+      | 0x80200000     |</span></span>
<span class="line"><span>        |                                        +----------------+</span></span>
<span class="line"><span>        |                                                ^</span></span>
<span class="line"><span>        +---------------- jump to _start ----------------+</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>Bootloader 負責找到並載入核心；核心開始執行後，會初始化自己的磁碟驅動並掛載 WUFS。<strong>載入器讀磁碟與核心掛載檔案系統，是兩個不同階段。</strong></p><h2 id="直接開機-文字與圖形入口" tabindex="-1">直接開機：文字與圖形入口 <a class="header-anchor" href="#直接開機-文字與圖形入口" aria-label="Permalink to &quot;直接開機：文字與圖形入口&quot;">​</a></h2><p><code>make run</code>、<code>make run-gui</code> 與 <code>.\\Start-WUWAOS.cmd gui</code> 採用直接開機。QEMU 以 <code>-kernel</code> 預先載入 <code>build/kernel.elf</code>，OpenSBI 直接交接到核心。</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>HOST: QEMU -kernel build/kernel.elf --&gt; kernel placed in RAM</span></span>
<span class="line"><span></span></span>
<span class="line"><span>GUEST: CPU -&gt; OpenSBI -&gt; kernel _start -&gt; kernel_main</span></span>
<span class="line"><span>                                            |</span></span>
<span class="line"><span>                                            +--&gt; UART shell</span></span>
<span class="line"><span>                                            |</span></span>
<span class="line"><span>                                            +--&gt; desktop, if devices exist</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br></div></div><p>兩條路徑都在 <code>0x80200000</code> 進入同一份 <code>arch/riscv/entry.S</code>。直接開機仍可掛載 WUFS，但啟動用的核心由 QEMU 載入。圖形模式目前使用這條路徑。<a href="./getting-started.html">啟動指令</a></p><h2 id="entry-s-先準備-c-所需的環境" tabindex="-1">entry.S：先準備 C 所需的環境 <a class="header-anchor" href="#entry-s-先準備-c-所需的環境" aria-label="Permalink to &quot;entry.S：先準備 C 所需的環境&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/arch/riscv/entry.S" target="_blank" rel="noreferrer">arch/riscv/entry.S（GitHub）</a>。</p><p><code>la sp, __stack_top</code> 設定 sp（堆疊指標）。C 的函式呼叫與區域資料會用到堆疊，因此必須先準備它。</p><p><code>1:</code> 到 <code>2:</code> 的迴圈逐 byte 清除 BSS（未明確指定初值的靜態資料區）。例如 PCB 陣列與頁面管理欄位會從零開始。清除 B 個 bytes 的成本是 O(B)，不另外配置記憶體。</p><p><code>call kernel_main</code> 才是兩個檔案的接點：組合語言以函式呼叫進入 C。若 C 意外返回，後面的 WFI（等待中斷指令）迴圈阻止 CPU 繼續執行未知內容。</p><h2 id="main-c-把子系統串起來" tabindex="-1">main.c：把子系統串起來 <a class="header-anchor" href="#main-c-把子系統串起來" aria-label="Permalink to &quot;main.c：把子系統串起來&quot;">​</a></h2><p>原始碼：<a href="https://github.com/johnson931128/WUWAOS/blob/main/kernel/boot/main.c" target="_blank" rel="noreferrer">kernel/boot/main.c（GitHub）</a>。</p><p>先安裝 trap（陷阱／例外入口），再顯示 UART 動畫、依 FDT 探索 PLIC 與 VirtIO 裝置、建立 Sv39 分頁映射並掛載 WUFS。接著註冊磁碟 IRQ、啟用 PLIC 通知與計時器，建立行程並進入排程器。若 FDT 找到 VirtIO GPU、tablet 與 keyboard，核心也建立 framebuffer、啟用輸入 queue 並繪製 Terminal 圖示；點擊後由 scheduler 建立獨立的 GUI shell。原始 PID 1 UART shell 仍存在；沒有圖形輸入設備時直接使用 UART。</p><p><code>fdt</code> 指向 FDT（硬體裝置樹），是韌體交給核心的硬體描述資料。核心用它尋找 VirtIO 裝置，實體頁配置器也會保留它占用的記憶體。</p><h2 id="開機動畫與觀察" tabindex="-1">開機動畫與觀察 <a class="header-anchor" href="#開機動畫與觀察" aria-label="Permalink to &quot;開機動畫與觀察&quot;">​</a></h2><p><code>ui/boot/splash.c</code> 透過 UART 輸出 ANSI 終端控制碼，以圖案中點為中心逐欄揭露 WUWAOS。字形以 5×7 位元資料表示，再用背景色與空格組成 70 欄實心筆畫，從螢光黃綠漸變到薄荷綠；不依賴特殊字型。這時尚未進入使用者模式；動畫中的忙等不是排程器，也不代表已啟用計時器中斷。色塊版本見 <a href="./../SPEC-13-block-splash.html">Spec 13</a>。</p><p>從專案根目錄在 PowerShell 執行 <code>wsl -d Ubuntu -- make run-disk</code>，會先看到 OpenSBI 和 flash 載入器的訊息，再看到 WUWAOS 字樣、核心與裝置資訊，最後進入 <code>wuwaos/&gt;</code>。</p><h2 id="virtio-圖形桌面" tabindex="-1">VirtIO 圖形桌面 <a class="header-anchor" href="#virtio-圖形桌面" aria-label="Permalink to &quot;VirtIO 圖形桌面&quot;">​</a></h2><p>QEMU 裝上 modern VirtIO GPU 與 tablet 後，kernel 以 FDT 找到裝置 MMIO 位址，不假設固定 VirtIO slot。GPU 建立 B8G8R8X8 的 1280×720 2D resource；CPU 繪製 shadow framebuffer，裝置使用另一段持久 DMA backing。Boot 資源建立仍同步等待，runtime 的 transfer／flush 改由 <code>gpu_poll</code> 分步完成，期間新 dirty 區域合併到下一次請求，不覆寫裝置仍在使用的 backing。VirtIO tablet 的絕對座標會縮放並夾限到畫面內。</p><h3 id="桌面-terminal-與-gui-shell" tabindex="-1">桌面 Terminal 與 GUI shell <a class="header-anchor" href="#桌面-terminal-與-gui-shell" aria-label="Permalink to &quot;桌面 Terminal 與 GUI shell&quot;">​</a></h3><p>目前視窗只繪製邊框與內容，沒有舊版深色實心陰影；既有截圖及 portable v1 保留先前單視窗外觀，詳見 <a href="./../SPEC-30-graphical-terminal.html">Spec 30</a>。2026-11-08 的多視窗與 GPU 復原尚未執行互動／視覺驗證（NOT_RUN）。</p><p>每次點擊左上角 Terminal 圖示會建立一個新 shell 視窗，最多四個；各有獨立 TTY、ANSI cell buffer 與輸入狀態。點擊視窗會置頂並取得鍵盤焦點，拖曳標題列移動，拖曳右下角調整視窗大小。畫面依 wallpaper → 底至頂的視窗 → cursor 合成，再提交 dirty 區域。視窗滿額或 shell 建立失敗會在桌面顯示提示。</p><p>關閉視窗會解除輸出 consumer、喚醒阻塞讀取並釋放 UI 引用。Shell 收到終端關閉錯誤後退出，持有該 TTY 的其他 OFD 仍須正常釋放才能回收 endpoint。Shell <code>exit</code> 後保留最後畫面，視窗可手動關閉。UART shell 的輸入與 GUI session 各自處理。</p><p>這是小型 kernel TTY，沒有 POSIX PTY、clipboard、job control 或 Ctrl+C。視窗大小調整只是裁切 viewport；終端模型仍固定 100×30，不會重排文字、通知 shell 改變列數或提供捲動檢視。GPU 故障會嘗試有界 reset／重建資源；無法復原時停用 GUI、保留 DMA storage，UART 路徑保留。架構分層見 <a href="./../SPEC-33-module-architecture.html">Spec 33</a>，本輪演算法與未驗證限制見<a href="https://github.com/johnson931128/WUWAOS/blob/main/plan.md" target="_blank" rel="noreferrer">計畫</a>；舊 <a href="./../SPEC-28-native-desktop.html">Spec 28</a>／<a href="./../SPEC-30-graphical-terminal.html">Spec 30</a> 保留當時驗收。</p><p>Windows portable 環境可直接使用 <code>.\\Start-WUWAOS.cmd gui</code>，QEMU 會開啟原生視窗，不需要另外的 VNC viewer。WSLg/Linux 圖形工作階段可用 <code>make run-gui GUI_DISPLAY=gtk</code>（或 <code>sdl</code>）。既有 Windows/WSL1 環境則可從 repo 根目錄以單一 PowerShell 指令啟動背景 QEMU 與原生 VNC viewer：</p><div class="language-powershell vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">tools</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">run</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">desktop.ps1</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>Launcher 會先檢查 Windows viewer、WSL 工具鏈及現有 QEMU，再建置並選擇未使用的 localhost VNC/QMP ports。關閉 viewer 會透過本次 QMP session 結束其 QEMU。TigerVNC viewer 可從<a href="https://github.com/TigerVNC/tigervnc/releases" target="_blank" rel="noreferrer">官方 releases</a>取得；若不在 PATH、標準安裝位置或 <code>build/tigervnc</code>，可用 <code>-ViewerPath</code> 指定。預設使用專案磁碟並保留客體寫入；<code>-Snapshot</code> 會改用關閉時刪除的暫存副本。launcher 的建置與序列輸出記錄在 <code>build/desktop-&lt;session-id&gt;</code>。手動進階流程可使用 <code>make run-gui-vnc</code> 加 Windows viewer。</p><h2 id="延伸資料" tabindex="-1">延伸資料 <a class="header-anchor" href="#延伸資料" aria-label="Permalink to &quot;延伸資料&quot;">​</a></h2><p>觀念參考：<code>notes/ch2 Operating-System Structures.md</code> 的開機與核心結構，<code>notes/ch12 I_O Systems.md</code> 的裝置 I/O 分層。WUWAOS 目前用自訂 GUI TTY 將 VirtIO input 連到既有 shell，不宣稱完整 PTY。實作細節與早期動畫驗收見<a href="./../CODE_GUIDE.html">程式碼導覽</a>及 <a href="./../SPEC-04-boot-splash.html">Spec 04</a>。</p>`,41)])])}const u=n(l,[["render",r]]);export{h as __pageData,u as default};
